{"command": "node -e "
import {listTools,callTool} from './server.mjs';
(async()=>{
  // unknown tool
  try{await callTool('nope',{});console.log('FAIL: unknown tool accepted');}catch(e){console.log('ok unknown:',e.message);}
  // empty title
  try{await callTool('note_create',{title:'',body:'B'});console.log('FAIL: empty title accepted');}catch(e){console.log('ok empty title:',e.message);}
  // missing body
  try{await callTool('note_create',{title:'A'});console.log('FAIL: missing body accepted');}catch(e){console.log('ok missing body:',e.message);}
  // empty note_id
  try{await callTool('note_get',{note_id:''});console.log('FAIL: empty id accepted');}catch(e){console.log('ok empty id:',e.message);}
  // nonexistent note
  try{await callTool('note_get',{note_id:'n999'});console.log('FAIL: missing note accepted');}catch(e){console.log('ok missing note:',e.message);}
  // happy path
  const c=await callTool('note_create',{title:'T',body:'B'});
  console.log('create:',JSON.stringify(c));
  const id=c.content[0].text.match(/n\d+/)[0];
  const g=await callTool('note_get',{note_id:id});
  console.log('get:',JSON.stringify(g));
  // schemas strict
  const tools=await listTools();
  console.log('additionalProperties false:',tools.every(t=>t.inputSchema.additionalProperties===false));
})();
" --input-type=module 2>&1"}

